INSERT INTO STUDENT
(
	HOMEPAGE_ID, GROUP_IDX, CATEGORY_IDX, TEACH_IDX, STUDENT_IDX, MEMBER_ID, MEMBER_KEY, APPLICANT_NAME, APPLICANT_BIRTH, web_id
	, APPLICANT_OLD, APPLICANT_SEX, APPLICANT_ZIPCODE, APPLICANT_ADDRESS, APPLICANT_ADDRESS_DETAIL, APPLICANT_PHONE, APPLICANT_CELL_PHONE, SELF_YN
	, STUDENT_NAME, STUDENT_BIRTH, STUDENT_SEX, STUDENT_ZIPCODE, STUDENT_ADDRESS, STUDENT_ADDRESS_DETAIL, STUDENT_SCHOOL, STUDENT_HACK, STUDENT_OLD
	, SELF_INFO_YN, APPLY_TYPE, APPLY_STATUS, ADD_DATE, ADD_ID, DELETE_YN, FAMILY_RELATION, FAMILY_NAME, FAMILY_CELL_PHONE, FAMILY_CONFIRM_YN, FAMILY_DESC
	, student_ban, student_remark, student_family_count,
	student_location_code,student_neis_cd,student_training_num,
	student_organization, student_rank, student_course_taken_yn, student_password, agree_codes
) VALUES
(
	#{homepage_id}, #{group_idx}, #{category_idx}, #{teach_idx}, #{student_idx}, #{member_id}, #{member_key}, #{applicant_name}, #{applicant_birth}, #{web_id}
	, #{applicant_old}, #{applicant_sex}, #{applicant_zipcode}, #{applicant_address}, #{applicant_address_detail}, #{applicant_phone}, #{applicant_cell_phone}, #{self_yn}
	, #{student_name}, #{student_birth}, #{student_sex}, #{student_zipcode}, #{student_address}, #{student_address_detail}, #{student_school}, #{student_hack}, #{student_old}
	, #{self_info_yn}, #{apply_type}, #{apply_status}, SYSDATE, #{add_id}, 'N', #{family_relation}, #{family_name}, #{family_cell_phone}, #{family_confirm_yn}, #{family_desc}
	, #{student_ban}, #{student_remark}, #{student_family_count},
	#{student_location_code}, #{student_neis_cd}, #{student_training_num},
	#{student_organization}, #{student_rank}, #{student_course_taken_yn}, #{student_password}, #{agree_codes}
)

