UPDATE STUDENT
SET DELETE_YN 					= 'Y'
	,APPLY_STATUS				= '99'
	
	, modify_id					= #{modify_id}
	, modify_date					= SYSDATE
WHERE
	HOMEPAGE_ID = #{homepage_id} AND GROUP_IDX = #{group_idx} AND CATEGORY_IDX = #{category_idx} AND TEACH_IDX = #{teach_idx}
	
	AND STUDENT_IDX = #{student_idx}

