SELECT
	REPLACE(a.END_DATE, '-', '')||'-'||LPAD(REPLACE(a.HOMEPAGE_ID, 'h', ''), 2, '0')||a.CATEGORY_IDX||LPAD(TEACH_IDX, 2, '0')||'-'||LPAD(b.NUM, 3, '0') AS NUM,
	a.END_DATE, a.TEACH_NAME, a.TEACH_STAGE, a.START_DATE||' ~ '||a.END_DATE AS TEACH_DATE,
	b.STUDENT_NAME, c.HOMEPAGE_NAME
FROM
	TEACH a, CMS_HOMEPAGE c, ( SELECT rownum num, Z.*
				FROM (
					SELECT
						STUDENT_IDX, STUDENT_NAME, APPLY_STATUS
					FROM
						STUDENT
					WHERE
						DELETE_YN 		= 'N'
						AND HOMEPAGE_ID 	= #{homepage_id}
						AND GROUP_IDX 		= #{group_idx}
						AND CATEGORY_IDX 	= #{category_idx}
						AND TEACH_IDX 		= #{teach_idx}
					ORDER BY STUDENT_NAME
				) Z ) b
WHERE
	a.HOMEPAGE_ID 		= c.homepage_id
	AND a.HOMEPAGE_ID 	= #{homepage_id}
	AND a.GROUP_IDX 	= #{group_idx}
	AND a.CATEGORY_IDX 	= #{category_idx}
	AND a.TEACH_IDX 	= #{teach_idx}
	AND b.STUDENT_IDX 	= #{student_idx}

SELECT
	COUNT(*)
FROM
	STUDENT
WHERE DELETE_YN 		= 'N'
	AND APPLY_STATUS 	!= '99'
	AND HOMEPAGE_ID 	= #{homepage_id}
	AND GROUP_IDX 		= #{group_idx}
	AND CATEGORY_IDX 	= #{category_idx}
	AND TEACH_IDX 		= #{teach_idx}
	AND MEMBER_KEY 		= #{member_key}

