SELECT result.*, CASE WHEN result.TEACH_COUNT = 0 THEN '2' WHEN result.ATTEND_CNT < 70 THEN '2' WHEN result.ATTEND_CNT >= 70 THEN '1' END AS STUDENT_STATUS FROM (SELECT a.TEACH_COUNT, b.*, CASE WHEN a.teach_count = 0 THEN 0 ELSE ((SELECT NVL(SUM(DECODE(status, '1', 1, '2', 1, 0)) - TRUNC(SUM(DECODE(status, '2', 1, 0))/3), 0) FROM TEACH_BOOK WHERE HOMEPAGE_ID = b.HOMEPAGE_ID AND GROUP_IDX = b.GROUP_IDX AND CATEGORY_IDX = b.CATEGORY_IDX AND TEACH_IDX = b.TEACH_IDX AND STUDENT_IDX = b.STUDENT_IDX)/a.teach_count)*100 END as ATTEND_CNT FROM (SELECT * FROM TEACH WHERE HOMEPAGE_ID = #{homepage_id} AND DELETE_YN = 'N' AND START_DATE > #{search_start_date} OR END_DATE < #{search_end_date} ) a, STUDENT b WHERE b.HOMEPAGE_ID = a.HOMEPAGE_ID AND b.GROUP_IDX = a.GROUP_IDX AND b.CATEGORY_IDX = a.CATEGORY_IDX AND b.TEACH_IDX = a.TEACH_IDX AND b.DELETE_YN = 'N' AND b.APPLY_STATUS = '1'
AND b.
) result

SELECT * FROM ( SELECT result.*, CASE WHEN result.TEACH_COUNT = 0 THEN '2' WHEN result.ATTEND_CNT < 70 THEN '2' WHEN result.ATTEND_CNT >= 70 THEN '1' END AS STUDENT_STATUS FROM (SELECT a.*, b.*, CASE WHEN a.teach_count = 0 THEN 0 ELSE ((SELECT NVL(SUM(DECODE(status, '1', 1, '2', 1, 0)) - TRUNC(SUM(DECODE(status, '2', 1, 0))/3), 0) FROM TEACH_BOOK WHERE HOMEPAGE_ID = b.HOMEPAGE_ID AND GROUP_IDX = b.GROUP_IDX AND CATEGORY_IDX = b.CATEGORY_IDX AND TEACH_IDX = b.TEACH_IDX AND STUDENT_IDX = b.STUDENT_IDX)/a.teach_count)*100 END as ATTEND_CNT FROM (SELECT * FROM TEACH
WHERE HOMEPAGE_ID = #{homepage_id}
AND DELETE_YN = 'N'
) a, STUDENT b WHERE b.HOMEPAGE_ID = a.HOMEPAGE_ID AND b.GROUP_IDX = a.GROUP_IDX AND b.CATEGORY_IDX = a.CATEGORY_IDX AND b.TEACH_IDX = a.TEACH_IDX AND b.DELETE_YN = 'N' AND b.APPLY_STATUS = '1' AND b.member_key = #{member_key} ) result ) WHERE student_status = '1'

